import ast
import sys

src = open(sys.argv[1], encoding="utf-8").read()
lo, hi = int(sys.argv[2]), int(sys.argv[3])
tree = ast.parse(src)


def names_defined(node):
    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
        return [node.name]
    out = []
    if isinstance(node, (ast.Assign, ast.AnnAssign)):
        tg = node.targets if isinstance(node, ast.Assign) else [node.target]
        for t in tg:
            for n in ast.walk(t):
                if isinstance(n, ast.Name):
                    out.append(n.id)
    return out


inside, outside = {}, {}
for node in tree.body:
    end = getattr(node, "end_lineno", node.lineno)
    box = inside if lo <= node.lineno and end <= hi else outside
    for n in names_defined(node):
        box[n] = node

used_in_inside, used_by_outside = set(), set()
for name, node in inside.items():
    for n in ast.walk(node):
        if isinstance(n, ast.Name) and n.id in outside:
            used_in_inside.add(n.id)
for node in tree.body:
